import sys

def min_rounds(X, Y):
    if X == Y:
        return 0
    if (X - Y) % 2 == 0:
        return 1
    return 2

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    T = int(data[0])
    index = 1
    results = []

    for _ in range(T):
        X = int(data[index])
        Y = int(data[index + 1])
        index += 2
        results.append(min_rounds(X, Y))

    for result in results:
        print(result)

if __name__ == "__main__":
    main()
